"""Data model."""

from dataclasses import dataclass


@dataclass
class Item:
    sku: str
    name: str
    quantity: int
    unit_price: float


def total_value(items):
    return sum(item.quantity * item.unit_price for item in items)


def low_stock(items, threshold=5):
    return [item for item in items if item.quantity < threshold]

"""Text reports."""

from .models import low_stock, total_value


def format_report(items):
    rows = [f"{item.sku:<8} {item.name:<20} {item.quantity:>5}" for item in items]
    rows.append(f"total value: {total_value(items):.2f}")
    for item in low_stock(items):
        rows.append(f"low stock: {item.sku}")
    return "\n".join(rows)

"""CSV storage."""

import csv

from .models import Item


def load_items(path):
    with open(path, newline="", encoding="utf-8") as handle:
        return [
            Item(row["sku"], row["name"], int(row["quantity"]), float(row["unit_price"]))
            for row in csv.DictReader(handle)
        ]


def find_item(items, sku):
    for item in items:
        if item.sku == sku:
            return item
    return None

import unittest

from inventory.models import Item, low_stock, total_value


class ModelTests(unittest.TestCase):
    def test_total_value(self):
        items = [Item("A1", "bolt", 10, 0.5), Item("B2", "nut", 4, 0.25)]
        self.assertEqual(total_value(items), 6.0)

    def test_low_stock(self):
        items = [Item("A1", "bolt", 10, 0.5), Item("B2", "nut", 4, 0.25)]
        self.assertEqual([item.sku for item in low_stock(items)], ["B2"])

import unittest

from inventory.models import Item
from inventory.store import find_item


class StoreTests(unittest.TestCase):
    def test_find_item(self):
        items = [Item("A1", "bolt", 10, 0.5)]
        self.assertEqual(find_item(items, "A1").name, "bolt")

    def test_find_missing_item(self):
        self.assertIsNone(find_item([], "Z9"))

